        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .card {
        width: min(100%, 680px);
        background: var(--surface);
        border: 1px solid rgba(141, 162, 196, 0.2);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        overflow: hidden;
