      }

      .lead {
        margin: 12px 0 0;
        max-width: 38rem;
        font-size: 1rem;
        line-height: 1.6;
        color: #dbeafe;
      }

      .card__body {
        padding: 32px;
      }

      form {
        display: grid;
        gap: 24px;
      }

      .form-field {
        padding: 24px;
        border-radius: var(--radius-md);
        background: linear-gradient(180deg, var(--surface) 0%, var(--surface-muted) 100%);
