      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        padding: 0;
        margin-bottom: 8px;
        font-size: 1.05rem;
        font-weight: 700;
        line-height: 1.4;
      }

      .field-hint {
        margin: 0 0 20px;
        color: var(--text-muted);
        line-height: 1.5;
      }

      .radio-list {
        display: grid;
        gap: 14px;
      }

      .radio-card {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 16px 18px;
        border: 1px solid var(--border);
        border-radius: var(--radius-sm);
        background: #fff;
        cursor: pointer;
        transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
      }

      .radio-card:hover {
        border-color: var(--border-strong);
        transform: translateY(-1px);
      }

      .radio-card:focus-within {
        border-color: var(--accent-strong);
        box-shadow:
          0 0 0 3px var(--accent-soft),
          0 0 0 1px var(--accent-strong);
      }

      .radio-card input[type="radio"] {
        width: 1.1rem;
        height: 1.1rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .radio-content {
        display: grid;
        gap: 2px;
        min-width: 0;
      }

      .radio-title {
        font-size: 1rem;
        font-weight: 600;
        color: var(--text);
      }

      .radio-description {
        color: var(--text-muted);
        font-size: 0.94rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      .submit-button {
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.4rem;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
        transition: transform 150ms ease, box-shadow 150ms ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 16px 28px rgba(37, 99, 235, 0.3);
      }

      .submit-button:focus-visible {
        outline: 3px solid var(--accent-soft);
        outline-offset: 3px;
      }

      .status-message {
        margin: 0;
        min-height: 1.5rem;
        color: var(--text-muted);
        font-weight: 600;
      }

      @media (max-width: 640px) {
        .card__hero,
        .card__body {
          padding: 24px;
        }

        .form-field {
          padding: 20px;
        }

        .actions {
          justify-content: stretch;
        }

        .submit-button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        .radio-card,
        .submit-button {
          border-color: ButtonText;
        }

        .submit-button {
          background: ButtonFace;
          color: ButtonText;
          box-shadow: none;
        }

        .radio-card:focus-within,
        .submit-button:focus-visible {
          outline: 2px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <main id="root"></main>
    <script>
      const notificationOptions = [
        {
          value: "email",
          label: "Email",
          description: "Receive updates in your inbox."
        },
        {
          value: "sms",
          label: "SMS",
          description: "Get timely alerts by text message."
        },
        {
          value: "push",
          label: "Push Notifications",
          description: "Stay informed with instant app notifications."
        }
      ];

      function RadioOption(option) {
        return `
          <label class="radio-card" for="${option.value}">
            <input id="${option.value}" type="radio" name="notificationPreference" value="${option.value}" required />
            <span class="radio-content">
              <span class="radio-title">${option.label}</span>
              <span class="radio-description">${option.description}</span>
            </span>
          </label>
        `;
      }

      function NotificationForm() {
        return `
          <form id="notification-form">
            <div class="form-field">
              <fieldset>
                <legend>How do you prefer to receive notifications?</legend>
                <p class="field-hint">Choose one option to tell us how you'd like product updates delivered.</p>
                <div class="radio-list">
                  ${notificationOptions.map(RadioOption).join("")}
                </div>
              </fieldset>
            </div>
            <p id="status-message" class="status-message" aria-live="polite"></p>
            <div class="actions">
              <button class="submit-button" type="submit">Submit</button>
            </div>
          </form>
        `;
      }

      function App() {
        return `
          <div class="page-shell">
            <section class="card" aria-labelledby="page-title">
              <div class="card__hero">
                <p class="eyebrow">Preferences</p>
                <h1 id="page-title">Choose your notification channel</h1>
                <p class="lead">
                  Personalize how you hear from us with a single selection in this quick setup form.
                </p>
              </div>
              <div class="card__body">
                ${NotificationForm()}
              </div>
            </section>
          </div>
        `;
      }

      document.getElementById("root").innerHTML = App();

      document.getElementById("notification-form").addEventListener("submit", function (event) {
        event.preventDefault();

        const formData = new FormData(event.currentTarget);
        const selected = formData.get("notificationPreference");
        const selectedOption = notificationOptions.find((option) => option.value === selected);
        const statusMessage = document.getElementById("status-message");

        statusMessage.textContent = selectedOption
          ? `Preference saved: ${selectedOption.label}.`
          : "Please choose a notification preference.";
      });
    </script>
  </body>
</html>
